/* cppi::c39509b0fdd3081ba5e33edb0aacf713132f0654111b38bdbafda36467ea514a */
select distinct request_id, start_date, end_date, pool, strategy_alternative, weight, start_date as business_date
from performance.tpm_tpm_atp_weights where request_id = 
(select max(request_id) from performance.tpm_tpm_atp_weights where start_date = '2025-04-16' and end_date = '2025-04-16')
and start_date = '2025-04-16' and end_date = '2025-04-16'

